const layout=[['C','±','%','÷'],['7','8','9','×'],['4','5','6','−'],['1','2','3','+'],['0','.','⌫','=']];
const names={'C':'Limpar','±':'Trocar sinal','%':'Porcentagem','÷':'Dividir','×':'Multiplicar','−':'Subtrair','+':'Somar','=':'Igual','⌫':'Apagar'};
let cur='0',acc=null,op=null,fresh=true,expr='';
const disp=document.getElementById('display'),ex=document.getElementById('expr'),msg=document.getElementById('msg');
function show(){disp.textContent=cur.replace('.',',');ex.textContent=expr;}
function calc(a,b,o){if(o==='+')return a+b;if(o==='−')return a-b;if(o==='×')return a*b;if(b===0)return null;return a/b;}
function fmt(n){return String(parseFloat(n.toPrecision(12)));}
function press(k){
msg.textContent='';
if(k>='0'&&k<='9'){if(fresh){cur=k;fresh=false;}else cur=cur==='0'?k:cur+k;}
else if(k==='.'){if(fresh){cur='0.';fresh=false;}else if(!cur.includes('.'))cur+='.';}
else if(k==='C'){cur='0';acc=null;op=null;fresh=true;expr='';}
else if(k==='⌫'){if(!fresh){cur=cur.length>1?cur.slice(0,-1):'0';if(cur==='-')cur='0';}}
else if(k==='±'){if(cur!=='0')cur=cur[0]==='-'?cur.slice(1):'-'+cur;}
else if(k==='%'){cur=fmt(parseFloat(cur)/100);}
else{
const v=parseFloat(cur);
if(op&&!fresh){const r=calc(acc,v,op);if(r===null){msg.textContent='Não é possível dividir por zero.';cur='0';acc=null;op=null;fresh=true;expr='';show();return;}acc=r;cur=fmt(r);}
else if(!op)acc=v;
if(k==='='){expr=op?expr+' '+fmt(v)+' =':expr;op=null;fresh=true;}
else{op=k;expr=fmt(acc)+' '+k;fresh=true;}
}
show();}
const keysEl=document.getElementById('keys');
for(const row of layout){for(const k of row){const b=document.createElement('button');b.type='button';b.textContent=k;b.setAttribute('aria-label',names[k]||k);if('÷×−+'.includes(k))b.className='op';if(k==='=')b.className='eq';b.addEventListener('click',()=>press(k));keysEl.appendChild(b);}}
document.addEventListener('keydown',e=>{
if(e.target&&e.target.tagName==='BUTTON'&&(e.key==='Enter'||e.key===' '))return;
const m={'*':'×','/':'÷','-':'−','+':'+',',':'.','.':'.','Enter':'=','=':'=','Backspace':'⌫','Escape':'C','%':'%'};
let k=null;if(e.key>='0'&&e.key<='9'&&e.key.length===1)k=e.key;else if(m[e.key])k=m[e.key];
if(k){e.preventDefault();press(k);}});
show();
